## Solution
```cpp[]
class Solution {
public:
    int uniquePaths(int m, int n) {
        vector<int> dp(n, 1);
        //initialized all to 1 to avoid doing redundant checks (i==0 && j==0) continue; step
        for(int i=1;i<m;i++){
            for(int j=0;j<n;j++){
                int left = (j==0)? 0 : dp[j-1];
                int up = (i==0)? 0 : dp[j];

                dp[j] = left + up;
            }
        }
        return dp[n-1];
    }
};
```

